SELECT typeof(CAST(map(1, 2) AS ARRAY<INT>)), CAST(map(1, 2) AS ARRAY<INT>);

SELECT typeof(TRY_CAST(map(1, 2) AS ARRAY<INT>)), TRY_CAST(map(1, 2) AS ARRAY<INT>);

SELECT typeof(CAST(v AS ARRAY<INT>)), CAST(v AS ARRAY<INT>) FROM VALUES (map(1, 2)), (NULL) AS t(v);

SELECT typeof(CAST(1 AS ARRAY<INT>)), CAST(1 AS ARRAY<INT>);

SELECT typeof(TRY_CAST(1 AS ARRAY<INT>)), TRY_CAST(1 AS ARRAY<INT>);

SELECT typeof(CAST(v AS ARRAY<INT>)), CAST(v AS ARRAY<INT>) FROM VALUES (1), (NULL) AS t(v);

SELECT typeof(CAST(array(1) AS INT)), CAST(array(1) AS INT);

SELECT typeof(TRY_CAST(array(1) AS INT)), TRY_CAST(array(1) AS INT);

SELECT typeof(CAST(v AS INT)), CAST(v AS INT) FROM VALUES (array(1)), (NULL) AS t(v);
